        list.add("a");
        list.add("b");
        SetUniqueList<String> setUniqueList = new SetUniqueList<>(list, new HashSet<>(list));
        Iterator<String> it = setUniqueList.iterator();
        it.next(); // "a"
        it.remove();
        assertEquals(1, setUniqueList.size());
        assertFalse(setUniqueList.contains("a"));
