        assertNotNull(setView);
        assertEquals(2, setView.size());
        assertTrue(setView.contains("a"));
        assertTrue(setView.contains("b"));
        assertTrue(setView instanceof org.apache.commons.collections.set.UnmodifiableSet);
    }
